import sqlite3, json, os, binascii
base='/home/box/agent-data/agents/cfde06bf-ba71-4db5-b377-4a6904467ce6'
con=sqlite3.connect(os.path.join(base,'store.db'))
cur=con.cursor()

# decode metadata
k,v=cur.execute("SELECT key,value FROM kv WHERE key='metadata'").fetchone()
if isinstance(v,bytes):
    try:
        meta=json.loads(v.decode())
    except:
        # hex?
        try:
            meta=json.loads(binascii.unhexlify(v).decode())
        except:
            print('meta raw', v[:200])
            meta=None
else:
    try:
        meta=json.loads(v)
    except:
        try:
            meta=json.loads(binascii.unhexlify(v).decode())
        except:
            print('meta str', v[:300])
            meta=None
print('METADATA', json.dumps(meta, indent=2)[:2000] if meta else None)

# request ids
k,v=cur.execute("SELECT key,value FROM kv WHERE key='requestIds'").fetchone()
reqs=json.loads(v if isinstance(v,str) else v.decode())
print('\n==== USER PROMPTS ====')
for r in reqs:
    p=(r.get('prompt') or '')[:300]
    print(r.get('at'), r.get('source'), p.replace('\n',' | '))
    print()

print('\n==== USER TURNS + ASSISTANT SNIPPETS ====')
for seq,id_,entry in cur.execute('SELECT seq,id,entry FROM transcript_entries ORDER BY seq'):
    e=json.loads(entry if isinstance(entry,str) else entry.decode())
    kind=e.get('kind')
    role=e.get('role')
    if role=='user':
        content=e.get('content') or ''
        if isinstance(content,list):
            content=' '.join(str(x) for x in content)
        print(f'\n--- USER seq={seq} ---')
        print(str(content)[:600])
    elif kind=='message' or e.get('message'):
        msg=e.get('message') or {}
        # various shapes
        text=''
        if isinstance(msg,str):
            text=msg
        elif isinstance(msg,dict):
            text=msg.get('content') or msg.get('text') or msg.get('body') or json.dumps(msg)[:400]
        # only print assistant-looking short
        if text and ('user' not in str(e.get('role',''))):
            t=str(text)[:250].replace('\n',' / ')
            if t.strip():
                print(f'  msg seq={seq} keys={list(msg.keys()) if isinstance(msg,dict) else type(msg)} :: {t}')
con.close()
