  "tool": {
    "tool": "AddMcpServer",
    "description": "Add an MCP server that isn't in the catalog to the user's Cursor account — use this when the user gives you a link or a launch command for a server that SearchPlugins doesn't know. Only call this after the user agrees to add it — confirm with a question widget first, since it changes the user's account configuration and the server can run commands or reach external services on their behalf. Provide EITHER a remote `url` OR a local `command` with `args` (and `env` for secrets) — not both. For a remote server's credentials, use `headers` for static bearer/API-key auth, or `auth` for an OAuth provider that publishes a pre-registered client ID (its `CLIENT_ID`, optional `CLIENT_SECRET`, and `scopes`) instead of supporting dynamic client registration. A remote server runs on the backend; a `command` server runs on your computer, which has node, npm, bun, python3, and uv, so `npx -y <pkg>` and `uvx <pkg>` both work — install anything else it needs with Shell first. That command also runs in this user's other agents, so say so when you confirm. Ask the user for the exact endpoint or command and any secrets rather than guessing; if you only have a link, open it first (WebFetch) to find the connection details. Newly added tools become available to you on your next message.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1,
          "description": "A short, unique name for the server, e.g. \"superpowers\"."
        },
        "url": {
          "type": "string",
          "minLength": 1,
          "description": "For a remote server: its MCP endpoint URL (https). Provide url OR command, not both."
        },
        "headers": {
          "type": "object",
          "description": "Optional HTTP headers for a remote server with static bearer/API-key auth, e.g. { \"Authorization\": \"Bearer <token>\" }. Ask the user for any secret rather than guessing."
        },
        "auth": {
          "type": "object",
          "properties": {
            "CLIENT_ID": {
              "type": "string",
              "minLength": 1,
              "description": "The OAuth client ID the server publishes for pre-registered clients."
            },
            "CLIENT_SECRET": {
              "type": "string",
              "description": "Optional OAuth client secret. Ask the user for it rather than guessing; many public clients need none."
            },
            "scopes": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "Optional OAuth scopes to request, e.g. [\"tweet.read\", \"offline.access\"]."
            }
          },
          "required": [
            "CLIENT_ID"
          ],
          "description": "Optional OAuth client settings for a remote server whose provider does not support dynamic client registration and instead publishes a pre-registered client ID. Use `headers` for static bearer/API-key auth; use `auth` only for OAuth. Remote servers only — never combine with `command`."
        },
        "command": {
          "type": "string",
          "minLength": 1,
          "description": "For a local (stdio) server: the executable to run on Grok Bot's computer, e.g. \"npx\". Provide command OR url, not both."
        },
        "args": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "description": "Arguments for the stdio command, e.g. [\"-y\", \"@acme/mcp-server\"]."
        },
        "env": {
          "type": "object",
          "description": "Environment variables for the stdio command, e.g. { \"API_KEY\": \"<token>\" }. Ask the user for any secret rather than guessing."
        }
      },
      "required": [
        "name"
      ]
    }
  }
}

{
  "mode": "single_tool",
  "namespace": "cursor",
  "namespaceDescription": "Native Cursor tools for this session. These are highly recommended and useful tools that you should use when the right situation arises. Don't be afraid to look at one if it seems relevant, even if you don't end up using it. You MUST read the tool schemas before calling them.\n\nHere are some crucial instructions:\n- AuthenticateMcpServer: Start authentication for a connector that needs auth.\n- AwaitExternalShell: Use to sleep and check shell progress. Never sleep using shell.\n- AwaitShell: Use to sleep and check shell progress. Never sleep using shell.\n- CheckSubagent: Inspect a running background subagent's status and recent actions.\n- CloudAgent: Launch and manage Cursor cloud coding agents for repository work.\n- CopyFromBox: Copy a file from your box onto the user's computer.\n- CopyToBox: Copy a file from the user's computer onto your box.\n- MessageSubagent: Send a new instruction into a running background subagent.\n- request_box_help: Hand your box's desktop to the user for a sign-in or manual step.\n- SearchPlugins: Search installable plugins/connectors when a task needs a service.\n- SendFeedback: Send the user's product feedback to the Cursor team when they ask.\n- StopSubagent: Abort a running background subagent.\n- TodoWrite: Use this tool to manage complex multi-step tasks.",
  "tool": {
    "tool": "CloudAgent",
    "description": "Manage Cursor cloud agents — background coding agents that run on a Cursor-managed VM or self-hosted worker, edit a GitHub repo on a branch, and open a pull request. Use this to spawn coding agents that make code changes, and to enumerate, inspect, follow up on, or clean up cloud agents.\n\nActions:\n- launch: start a new cloud agent. Requires prompt + repo_url (a GitHub repo the user has connected to Cursor); repo_url is optional when launching into a saved environment (see Environment below), which supplies its own repos. Optional starting_ref, model, model_params, title (used verbatim as the agent's title instead of the auto-generated prompt summary), and environment (where it runs — see Environment below). Returns the agent id and its cursor.com URL. You're revived automatically when the run finishes — don't poll it — and the completion message includes the path to its full transcript (auto-dumped to a file on your box), so you can inspect it with Shell or Read without calling dump.\n- list: enumerate cloud agents. scope defaults to \"launched\" (agents started via this tool this session); pass scope: \"all\" to see every cloud agent on the account.\n- models: list the model ids you can launch with and, per model, the params each accepts with allowed values. Use only to resolve a model or settings the user explicitly requested; do not browse the catalog to choose a model yourself.\n- get: status of one agent (agent_id) — state, branch, PR, change stats. For a one-off status check; for being notified on completion, use watch instead of polling get. To read the actual code changes, use the branch from here over the GitHub API, never a local clone: `gh pr diff` for runs with a PR, or `gh api` against the branch for runs without one.\n- dump: write the agent's FULL conversation transcript (agent_id) to a file on your box (under cloud-agent-transcripts/ in your working directory — the result gives the exact path), then use Shell to grep it or Read to read it. Limited to agents you manage this session (launched, watched, or replied to) — for others, 'watch' it first. Returns the path + size, not the contents. JSONL, one message per line with full detail (text, reasoning, tool calls with args, tool results). The final assistant report is the last line — `tail -n 1` it for just the final output. Works while running (partial) and when finished. Use this for mid-run inspection or to re-dump; a finished run you launched/watched is auto-dumped to the same path already (its completion message has the path). Use this instead of sending a 'reply' that asks the agent to summarize.\n- watch: register to be revived automatically when an existing agent (agent_id) finishes — use this for agents you didn't launch this session (launch already watches its own). You keep working and are revived with the result; never poll get in a loop.\n- reply: send a follow-up prompt to an existing agent (agent_id + prompt). By default the follow-up is queued and processed only after the agent's current turn finishes; pass interrupt: true to interrupt the in-flight turn and have the agent start working on your message immediately (no-op if it isn't currently running — it just sends normally). Like launch, you're revived automatically when the follow-up run finishes — don't poll it.\n- rename: retitle an existing agent (agent_id + title). Works on a running agent, so use it when taking ownership of an in-flight run (e.g. prefixing a title) rather than relaunching. The title is used verbatim and shows on cursor.com, in the IDE sidebar, and on mobile.\n- cancel / archive / unarchive: manage lifecycle (agent_id). These run immediately — no confirmation needed. Archiving keeps the agent's pull request open.\n- delete: permanently delete an agent. Confirm with the user (e.g. a SendMessage widget) first, then call with confirm: true.\n- list_artifacts: list files the agent saved under its workspace artifacts.\n\nEnvironment (worker pools / private workers): set where the agent runs with the environment param on launch.\n- Omit environment, or pass {\"type\":\"cloud\"}, for a Cursor-managed Linux VM (the default).\n- Pass {\"type\":\"pool\"} to run on any eligible self-hosted pool for the repo (\"shared pool\" / self-hosted pool).\n- Pass {\"type\":\"pool\",\"name\":\"<pool-name>\"} for a specific named pool the user or task names (examples: \"mobile-ios-mac\", \"mobile-ios-mac-legacy\"). Use this when the work needs Mac/iOS simulators, a team's shared workers, or any runtime the default cloud VM cannot provide.\n- Pass {\"type\":\"machine\",\"name\":\"<worker-name>\"} for one specific private worker (\"My Machine\").\n- Pass {\"type\":\"environment\",\"name\":\"<environment-name>\"} (or \"id\" with its public id) to launch into a saved Cloud Agents environment from the user's cursor.com dashboard — the run gets that environment's custom env vars, egress rules, install commands, and (for multi-repo environments) all configured repos, on a Cursor VM. repo_url is then optional and defaults to the environment's primary repo. Use this when the user names a saved environment or the task needs specific environment variables or egress settings.\n- For pool and machine, a single active team is selected automatically; set team_id only when the user belongs to multiple active teams.\n- If the user asks to launch on a pool / self-hosted workers / a named pool / a saved environment, pass environment on that same launch call.\n\nModel configuration: only pass model (id) and model_params (structured params like thinking/effort/context/fast) when the user explicitly requests that model or those settings for this cloud agent. model_params requires model because parameter schemas are model-specific. Never select a model based on the task, catalog order, availability, or your own preference. For a user-requested override, discover valid ids and per-model params/values with the 'models' action first; params are validated against the catalog. Otherwise omit both: a launch uses the user's saved/team/global cloud-agent default, while a reply keeps the cloud agent's current model. Never encode params into the model id string — keep model a clean id and put settings in model_params.\n\nAttaching images: on launch and reply, pass images: [{\"url\":\"file:///workspace/shot.png\"}] to show the cloud agent a screenshot, mock, chart, or repro. The agent actually sees them, so never paste an image as a markdown ![](...) in the prompt. Use absolute file:// URLs — a path in your own box (file:///workspace/…) or a host attachment path; https:// is rejected, so download such an image to a file first. There is no caption field: say what each image shows in the prompt text.\n\nCloud agents run remotely and do not edit the user's local files — results come back as a branch/PR. Authentication is handled for the signed-in user; never ask for an API key.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "action": {
          "type": "string",
          "enum": [
            "launch",
            "list",
            "models",
            "get",
            "dump",
            "watch",
            "reply",
            "rename",
            "cancel",
            "archive",
            "unarchive",
            "delete",
            "list_artifacts"
          ],
          "description": "What to do: launch (start a new cloud agent on a repo — you're revived automatically when it finishes), list (enumerate cloud agents), models (list available model ids and the params each accepts; use only for a user-requested model override), get (status of one), dump (write the agent's full conversation transcript to a file on your box so you can grep it with Shell or read it with Read; tail the last line for the final report), watch (be revived when an existing agent finishes, without polling), reply (send a follow-up prompt to an agent — queued by default, or pass interrupt:true to interrupt the running turn and deliver it now; you're revived automatically when the follow-up run finishes, like launch), rename (retitle an existing agent), cancel (stop the active run), archive/unarchive, delete (permanent), list_artifacts."
        },
        "prompt": {
          "type": "string",
          "description": "Instruction text. Required for launch and reply."
        },
        "images": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "url": {
                "type": "string",
                "minLength": 1,
                "description": "file:// URL of the image, e.g. file:///workspace/shot.png."
              }
            },
            "required": [
              "url"
            ]
          },
          "description": "Optional image(s) to attach to a launch or reply — a screenshot, mock, or chart the cloud agent needs to see. The agent actually sees them (they ride its vision channel), so never paste an image as markdown in the prompt. Pass an absolute file:// URL: a path in your own box (file:///workspace/shot.png) or a host attachment path. https:// is not supported here — download it to a file first. Describe what each image shows in the prompt itself; there is no caption field."
        },
        "repo_url": {
          "type": "string",
          "description": "Required for launch, except when environment.type is \"environment\" (a saved environment supplies its own repos; if passed anyway it must be that environment's primary repo). GitHub repository URL (e.g. https://github.com/owner/repo) the user has connected to Cursor."
        },
        "starting_ref": {
          "type": "string",
          "description": "Optional for launch. Branch or commit to start from; defaults to the repo's default branch."
        },
        "model": {
          "type": "string",
          "description": "Optional model id for launch/reply. Pass only when the user explicitly requests a model override; never choose one based on the task, catalog order, or your own preference. Use the 'models' action to resolve a user-requested model name. For launch, omit to use the user's saved/team/global cloud-agent default. For reply, omit to keep the cloud agent's current model."
        },
        "model_params": {
          "type": "object",
          "description": "Optional structured model parameters for launch/reply, as a map of param id to string value (e.g. {\"thinking\":\"true\",\"effort\":\"xhigh\"}). Requires model because parameter schemas are model-specific. Pass only for model settings the user explicitly requests; otherwise omit. Use the 'models' action to see the requested model's params, allowed values, and compatibility restrictions. Cloud agents always run in Max Mode, but parameter compatibility remains model-specific. Booleans are the strings \"true\"/\"false\"."
        },
        "title": {
          "type": "string",
          "description": "Title for the cloud agent shown in the UI, used verbatim instead of the auto-generated summary of the prompt. Optional for launch; required for rename."
        },
        "environment": {
          "anyOf": [
            {
              "type": "object",
              "properties": {
                "type": {
                  "type": "string",
                  "const": "cloud"
                }
              },
              "required": [
                "type"
              ]
            },
            {
              "type": "object",
              "properties": {
                "type": {
                  "type": "string",
                  "const": "pool"
                },
                "name": {
                  "type": "string",
                  "minLength": 1
                },
                "team_id": {
                  "type": "integer",
                  "exclusiveMinimum": 0
                }
              },
              "required": [
                "type"
              ]
            },
            {
              "type": "object",
              "properties": {
                "type": {
                  "type": "string",
                  "const": "machine"
                },
                "name": {
                  "type": "string",
                  "minLength": 1
                },
                "team_id": {
                  "type": "integer",
                  "exclusiveMinimum": 0
                }
              },
              "required": [
                "type",
                "name"
              ]
            },
            {
              "type": "object",
              "properties": {
                "type": {
                  "type": "string",
                  "const": "environment"
                },
                "id": {
                  "type": "string",
                  "minLength": 1
                },
                "name": {
                  "type": "string",
                  "minLength": 1
                }
              },
              "required": [
                "type"
              ]
            }
          ],
          "description": "Optional for launch. Sets where the cloud agent runs. Example for a named shared pool: {\"type\":\"pool\",\"name\":\"mobile-ios-mac\"}. Example for any eligible shared pool: {\"type\":\"pool\"}. Example for a saved Cloud Agents environment: {\"type\":\"environment\",\"name\":\"evals\"}. Omit (or {\"type\":\"cloud\"}) for a Cursor-managed VM."
        },
        "interrupt": {
          "type": "boolean",
          "description": "Optional for reply. false/omitted (default) queues the follow-up so it's processed only after the current run finishes (today's behavior). true interrupts the agent's currently-running turn and delivers the message immediately, so it starts processing now instead of waiting. If the agent isn't currently running, interrupt has no effect — the message is just sent normally."
        },
        "agent_id": {
          "type": "string",
          "description": "The agent id (bc-…). Required for get, dump, watch, reply, rename, cancel, archive, unarchive, delete, list_artifacts."
        },
        "scope": {
          "type": "string",
          "enum": [
            "launched",
            "all"
          ],
          "description": "For list: 'launched' (default) returns only agents started via this tool this session; 'all' returns every cloud agent on the user's account."
        },
        "include_archived": {
          "type": "boolean",
          "description": "For list: include archived agents (default false)."
        },
        "limit": {
          "type": "integer",
          "exclusiveMinimum": 0,
          "description": "For list: max agents to return (default 20)."
        },
        "confirm": {
          "type": "boolean",
          "description": "Required true for delete. First confirm with the user via a SendMessage widget, then call again with confirm: true."
        }
      },
      "required": [
        "action"
      ]
    }
  }
}
